sourcesContent:
.expand-enter-active,
.expand-leave-active {
    transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
}

.expand-enter,
.expand-leave-to {
    height: 0;
    opacity: 0;
}

.globe {
    box-shadow: 0 0 150px #e8fcd4;
}

@media (max-width: 768px) {
    .globe {
        box-shadow: 0 0 100px #e8fcd4;
    }
}

/* Marker wrapper */
.marker {
    position: absolute;
    transform: translate(-50%, -50%);
    cursor: pointer;
}


/* Dot grows on hover */
.marker:hover .dot {
    transform: scale(2);
}

.marker:hover {
    z-index: 10;
}

/* Label box */
.label {
    left: 50%;
    transform: translateX(-50%) translateY(10px);
    padding: 8px 12px;
    border-radius: 8px;
    opacity: 0;
    pointer-events: none;
    transition:
        opacity 0.35s ease,
        transform 0.35s ease;
}

/* Hover reveal animation */
.marker:hover .label {
    opacity: 1;
    transform: translateX(-50%) translateY(0px);
}

.p-active {
    opacity: 1;
    transform: translateX(-50%) translateY(0px);
}

.line-active {
    opacity: 1 !important;
}

/* Optional leader line */
.leader-line {
    position: absolute;
    width: 1px;
    height: 40px;
    top: -40px;
    left: 50%;
    transform: translateX(-50%);
    background: #e8fcd4;
    transition: opacity 0.35s ease;
    opacity: 0;
}

.marker:hover .leader-line {
    opacity: 1;
}
